SELECT p.subject_id, p.gender, p.anchor_age, p.anchor_year, p.anchor_year_group, d.deathtime, s.stay_id, s.first_careunit, s.last_careunit, s.intime, s.outtime, s.los, m.micro_specimen_id, m.order_provider_id, m.chartdate, m.charttime, m.spec_itemid, m.spec_type_desc, m.test_seq, m.storedate, m.storetime, m.test_itemid, m.test_name, m.org_itemid, m.org_name, m.isolate_num, m.quantity, m.ab_itemid, m.ab_name, m.dilution_text, m.dilution_comparison, m.dilution_value, m.interpretation, percent_rank() OVER (ORDER BY p.subject_id) AS composite_risk_percentile, (SELECT CAST(COUNT(CASE WHEN d.deathtime IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS in_hospital_mortality_rate, (SELECT CAST(COUNT(CASE WHEN m.micro_specimen_id IN (SELECT micro_specimen_id FROM microbiologyevents WHERE (value LIKE '%sepsis%' OR value LIKE '%septic%')) THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS major_complication_rate, (SELECT AVG(s.los) FROM icustays s) AS median_survival_days FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN microbiologyevents m ON a.hadm_id = m.hadm_id JOIN icustays s ON a.subject_id = s.subject_id WHERE p.gender = 'M' AND p.anchor_age BETWEEN 73 AND 83 AND m.test_name ILIKE '%pneumonia%' AND (SELECT percentile_cont(0.75) within GROUP (ORDER BY COUNT(comorbidity_id)) FROM patient_comorbidities WHERE patient_id = p.subject_id) > 0;